<template>
 <section data-general-maintenance><h2>商品适用范围</h2><p class="muted">专属型号使用现有型号声明；公用商品使用设备类型和供应商明确确认的必要条件。资料集中维护，不写入权益包。</p>
 <el-radio-group :model-value="mode" aria-label="适用方式" @change="changeMode"><el-radio-button value="general">通用条件</el-radio-button><el-radio-button value="model">明确型号</el-radio-button></el-radio-group>
 <CompatibilityManager v-if="mode==='model'" ref="modelManager" :target="skuIds?.[0]?{kind:'sku',id:skuIds[0]}:undefined" :initial-target-ids="skuIds" :device-sku-id="deviceSkuId" @navigate="emit('navigate',$event)"/>
 <template v-else><div class="tools"><el-input v-model="search" clearable placeholder="搜索商品或资料来源" aria-label="搜索通用适用"/><el-button v-if="store.can('product:compatibility:create')" type="primary" data-new-general @click="open()">登记适用范围</el-button></div>
 <el-alert v-if="!canMaintain" title="当前仅可查看；维护需要兼容性操作权限。" type="info" :closable="false"/><p v-if="skuIds?.length">当前明确选择 {{skuIds.length}} 个实际 SKU；新增规格不会自动继承。</p>
 <el-empty v-if="!rows.length" description="暂无通用条件声明；没有声明不等于明确不兼容"/>
 <article v-for="c in paged" :key="c.id" class="claim" :data-general-claim="c.id"><strong>{{label(c.skuId)}}</strong><p>通用条件 · {{c.deviceTypeIds.map(typeName).join('、')}} · {{capabilityLabels[c.capability]}}</p><p>{{c.conditions.length?c.conditions.map(x=>conditionText(store.data,x)).join('；'):'必要条件待完善'}} · {{c.verification==='confirmed'?'已确认':'待核验'}} · {{c.conclusion==='incompatible'?'不适用':'适用'}}</p><p>资料来源：{{c.source}}</p><el-alert v-if="generalReferenceProblem(store.data,c)" :title="generalReferenceProblem(store.data,c)" type="warning" :closable="false"/><el-button v-if="store.can('product:compatibility:update')" link @click="open(c)">编辑适用范围</el-button><el-button v-if="store.can('product:compatibility:delete')" link type="danger" @click="remove(c)">删除此声明</el-button></article>
 <el-pagination v-if="rows.length>10" v-model:current-page="page" :page-size="10" :total="rows.length" layout="prev,pager,next"/>
 </template>
 <el-dialog v-model="opened" title="维护商品适用范围" width="min(960px,96vw)" :close-on-click-modal="false" :before-close="close" data-general-editor><el-form label-position="top" :disabled="saving">
 <el-form-item label="1. 本次实际影响的销售 SKU"><el-select v-model="targets" multiple filterable :disabled="!!editing" aria-label="适用范围目标 SKU" style="width:100%"><el-option v-for="s in accessories" :key="s.id" :value="s.id" :label="label(s.id)"/></el-select></el-form-item>
 <el-form-item label="2. 适用方式"><el-tag>通用条件</el-tag><span class="muted">指定型号请使用页面上的“明确型号”入口。</span></el-form-item>
 <el-form-item label="3. 设备产品类型"><el-select v-model="form.deviceTypeIds" multiple filterable aria-label="通用适用设备类型" style="width:100%"><el-option v-for="t in hostTypes" :key="t.id" :value="t.id" :label="t.name"/></el-select></el-form-item>
 <el-alert title="只勾选设备类型不能确认适用。以下条件必须来自供应商对当前能力的明确依据；名称或单个接口不能自动证明兼容。" type="info" :closable="false"/>
 <div class="conditions"><h3>必要条件（全部满足）</h3><div v-for="(c,i) in form.conditions" :key="i" class="condition"><el-select v-model="c.attributeId" filterable :aria-label="`条件参数 ${i+1}`" @change="c.value=c.operator==='in'?[]:''"><el-option v-for="p in conditionParams" :key="p.id" :label="p.name" :value="p.id"/></el-select><el-select v-model="c.operator" :aria-label="`条件运算 ${i+1}`" @change="c.value=c.operator==='in'?[]:''"><el-option label="等于" value="eq"/><el-option label="属于指定值" value="in"/></el-select><el-select :model-value="c.value" :multiple="c.operator==='in'" :key="c.operator" :aria-label="`条件值 ${i+1}`" @update:model-value="c.value=$event"><el-option v-for="v in store.data.params.find(p=>p.id===c.attributeId)?.values||[]" :key="v" :label="v" :value="v"/></el-select><el-button link type="danger" @click="form.conditions.splice(i,1)">移除</el-button></div><el-button data-add-general-condition @click="form.conditions.push({kind:'attribute',attributeId:'',operator:'eq',value:''})">增加必要条件</el-button></div>
 <el-form-item label="4. 供应商或其他正式资料依据"><el-input v-model="form.source" type="textarea" maxlength="2000" aria-label="通用适用资料来源" placeholder="保留真实确认依据；原文不会作为表达式执行"/></el-form-item>
 <el-form-item label="5. 核验状态"><el-select v-model="form.verification" aria-label="通用核验状态"><el-option label="待核验" value="pending"/><el-option label="已确认" value="confirmed"/></el-select></el-form-item><el-form-item label="结论"><el-select v-model="form.conclusion" aria-label="通用适用结论"><el-option label="满足条件时适用" value="compatible"/><el-option label="满足条件时不适用" value="incompatible"/></el-select></el-form-item>
 <details><summary>其他能力与备注</summary><el-form-item label="能力"><el-select v-model="form.capability" aria-label="通用声明能力"><el-option label="基本使用" value="basic"/><el-option label="快充能力" value="fast-charge"/><el-option label="指定能力" value="other"/></el-select></el-form-item><el-input v-model="form.note" placeholder="备注"/></details>
 <h3>6. 实际设备试算</h3><el-select v-model="previewDevice" filterable clearable aria-label="通用范围试算设备" placeholder="选择实际设备或标准型号"><el-option-group label="实际设备"><el-option v-for="s in devices.skus" :key="s.id" :value="`sku:${s.id}`" :label="`${s.name} · ${s.spec}`"/></el-option-group><el-option-group label="标准型号（不推测规格事实）"><el-option v-for="m in devices.models" :key="m.key" :value="`model:${m.key}`" :label="m.label"/></el-option-group></el-select>
 </el-form>
 <el-alert v-if="preview.message" :title="preview.message" type="warning" :closable="false"/>
 <section class="preview" data-general-preview><h3>本次保存影响</h3><p>明确影响 {{targets.length}} 个 SKU；不会覆盖未选规格或其他人工声明。</p><p v-for="(item,i) in preview.items" :key="i">{{label(item.skuId)}}：{{item.state==='duplicate'?'重复跳过':item.state==='edit'?'编辑':'新增'}} · {{item.message}} · 已有 {{existing(item.skuId)}} 条资料</p><p v-if="oppositeCount">存在 {{oppositeCount}} 条可能相反的已有依据；保存不会覆盖，请使用实际设备核对冲突。</p></section>
 <section v-if="previewDevice&&preview.ok" data-general-trial><article v-for="r in trial" :key="r.id"><strong>{{label(r.id)}}：{{r.allowed?'可进入正常候选':'不能进入正常候选'}}</strong><p>{{r.reason}}</p><CompatibilityEvidence :evidence="r.evidence"/></article></section>
 <el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <template #footer><el-button :disabled="saving" @click="close(()=>opened=false)">取消</el-button><el-button type="primary" :disabled="!preview.ok||!targets.length||!store.can(`product:compatibility:${editing?'update':'create'}`)" :loading="saving" data-save-general @click="save">确认保存这些 SKU 的资料</el-button></template></el-dialog>
 </section>
</template>
<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import {onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useCatalogStore} from '../../stores/catalog'
import {isRealSku} from '../../domain/catalogIdentity'
import {compatibilityRecordRole} from '../../domain/deviceResolution'
import {applyGeneralChanges,generalReferenceProblem,type GeneralCompatibilityClaim,type GeneralDraft,type GeneralChange} from '../../domain/generalCompatibility'
import {copy} from '../../domain/benefitSales/commands'
import {saleQuery,saleLabel,deviceOptions,deviceFromKey} from '../../domain/benefitSales/query'
import {compatibilityFamilyTypeId} from '../../domain/deviceResolution'
import {capabilityLabels,conditionText} from './compatibilityPresentation'
import CompatibilityEvidence from './CompatibilityEvidence.vue'
import CompatibilityManager from './CompatibilityManager.vue'
const props=defineProps<{skuIds?:string[];deviceSkuId?:string;modelKey?:string}>(),emit=defineEmits<{navigate:[tab:'results'|'legacy']}>(),store=useCatalogStore()
const mode=ref('general'),search=ref(''),page=ref(1),opened=ref(false),saving=ref(false),error=ref(''),targets=ref<string[]>([]),editing=ref<GeneralCompatibilityClaim>(),basis=ref(''),baseline=ref(''),previewDevice=ref(''),modelManager=ref<InstanceType<typeof CompatibilityManager>>()
const blank=():Omit<GeneralDraft,'skuId'>=>({deviceTypeIds:[],capability:'basic',conditions:[],conclusion:'compatible',verification:'pending',source:'',note:''}),form=ref(blank())
const canMaintain=computed(()=>store.can('product:compatibility:create')||store.can('product:compatibility:update')),devices=computed(()=>deviceOptions(store.data)),accessories=computed(()=>store.data.skus.filter(s=>isRealSku(store.data,s)&&compatibilityRecordRole(store.data,s.id)==='accessory')),hostTypes=computed(()=>store.data.productTypes.filter(t=>t.catalogRole==='host'&&t.status==='enabled')),conditionParams=computed(()=>store.data.params.filter(p=>p.identityRole!=='host-model'&&p.values.length))
const label=(id:string)=>{const l=saleLabel(store.data,id);return `${l.name} · ${l.spec||l.code}`},typeName=(id:string)=>store.data.productTypes.find(t=>t.id===id)?.name||'类型引用失效'
const rows=computed(()=>(store.data.generalCompatibilityClaims||[]).filter(c=>(!props.skuIds?.length||props.skuIds.includes(c.skuId))&&`${label(c.skuId)} ${c.source}`.toLowerCase().includes(search.value.trim().toLowerCase()))),paged=computed(()=>rows.value.slice((page.value-1)*10,page.value*10))
const changes=computed<GeneralChange[]>(()=>targets.value.map(skuId=>editing.value?{kind:'edit',id:editing.value.id,revision:editing.value.revision,draft:{...copy(form.value),skuId}}:{kind:'add',draft:{...copy(form.value),skuId}}))
const preview=computed(()=>{const data=copy(store.data);let n=0;return {...applyGeneralChanges(data,changes.value,()=>`preview-${++n}`,new Date().toISOString()),data}})
const trial=computed(()=>{if(!preview.value.ok||!previewDevice.value)return [];const ids=[...new Set(targets.value.map(id=>{const s=store.data.skus.find(s=>s.id===id);return s?compatibilityFamilyTypeId(store.data,s.familyId):''}))],q=saleQuery(preview.value.data,{mode:'free',categoryId:'',productTypeIds:ids,device:deviceFromKey(previewDevice.value)});return targets.value.map(id=>{const match=[...q.groups.flatMap(g=>g.candidates)].find(c=>c.id===id),diagnosis=q.groups.flatMap(g=>g.diagnostics).find(d=>d.id===id);return {id,allowed:!!match,reason:diagnosis?.reason||match?.note||'当前范围或设备资料无法核验',evidence:match?.match?.evidence||[...q.compatibility?.sales||[],...q.compatibility?.pending||[],...q.compatibility?.excluded||[],...q.compatibility?.unavailable||[]].find(m=>m.target.id===id)?.evidence||[]}})})
const existing=(id:string)=>(store.data.generalCompatibilityClaims||[]).filter(c=>c.skuId===id).length+store.data.compatibilities.filter(c=>(c.targetId||c.accessorySkuId)===id).length
const oppositeCount=computed(()=>store.data.compatibilities.filter(c=>targets.value.includes(c.targetId||c.accessorySkuId)&&form.value.deviceTypeIds.includes(c.host.productTypeId)&&(c.capability||'basic')===form.value.capability&&(c.conclusion==='incompatible')!==(form.value.conclusion==='incompatible')).length+(store.data.generalCompatibilityClaims||[]).filter(c=>c.id!==editing.value?.id&&targets.value.includes(c.skuId)&&c.deviceTypeIds.some(id=>form.value.deviceTypeIds.includes(id))&&c.capability===form.value.capability&&(c.conclusion==='incompatible')!==(form.value.conclusion==='incompatible')).length)
function signature(){return JSON.stringify([targets.value,form.value,editing.value?.id])}
function open(c?:GeneralCompatibilityClaim){editing.value=c?copy(c):undefined;targets.value=c?[c.skuId]:[...(props.skuIds||[])];form.value=c?{deviceTypeIds:[...c.deviceTypeIds],capability:c.capability,conditions:copy(c.conditions),conclusion:c.conclusion,verification:c.verification,source:c.source,note:c.note}:blank();basis.value=JSON.stringify(store.data.generalCompatibilityClaims||[]);baseline.value=signature();previewDevice.value=props.deviceSkuId?`sku:${props.deviceSkuId}`:props.modelKey?`model:${props.modelKey}`:'';error.value='';opened.value=true}
function beforeUnload(e:BeforeUnloadEvent){if(opened.value&&(saving.value||signature()!==baseline.value)){e.preventDefault();e.returnValue=''}}
window.addEventListener('beforeunload',beforeUnload)
onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload))
async function discard(){if(saving.value)return false;if(!opened.value||signature()===baseline.value)return true;try{await ElMessageBox.confirm('适用资料有未保存修改，确定放弃？','未保存资料',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑'});opened.value=false;return true}catch{return false}}
async function close(done:()=>void){if(await discard())done()}
async function changeMode(value:string|number|boolean|undefined){if(await discard()&&(!modelManager.value||await modelManager.value.canDiscard())){opened.value=false;mode.value=String(value)}}
onBeforeRouteLeave(discard);onBeforeRouteUpdate(discard)
watch(()=>[store.activeUserId,store.previewUserId],()=>{opened.value=false;targets.value=[];editing.value=undefined;form.value=blank();error.value='';previewDevice.value='';baseline.value='';basis.value=''})
async function save(){saving.value=true;error.value='';const owner=JSON.stringify([store.activeUserId,store.previewUserId]),stamp=signature();try{const result=await store.commitGeneralCompatibility(changes.value,basis.value,()=>owner===JSON.stringify([store.activeUserId,store.previewUserId])&&signature()===stamp);if(owner!==JSON.stringify([store.activeUserId,store.previewUserId]))return;if(!result.ok){error.value=result.message||'保存失败';return}opened.value=false;ElMessage.success('适用范围已保存')}catch(e){if(owner===JSON.stringify([store.activeUserId,store.previewUserId]))error.value=String(e)}finally{saving.value=false}}
async function remove(c:GeneralCompatibilityClaim){try{await ElMessageBox.confirm('只删除此声明，已确认清单的历史依据保持不变。','删除适用声明');const result=await store.commitGeneralCompatibility([{kind:'remove',id:c.id,revision:c.revision}],JSON.stringify(store.data.generalCompatibilityClaims||[]));if(!result.ok)ElMessage.error(result.message||'删除失败')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(String(e))}}
</script>
<style scoped>.tools{display:flex;gap:12px;margin:16px 0}.tools .el-input{max-width:450px}.claim{padding:14px 0;border-bottom:1px solid var(--el-border-color)}.muted{color:var(--el-text-color-secondary)}.condition{display:flex;gap:8px;margin:10px 0}.condition .el-select{min-width:0;flex:1}.conditions,.preview{padding:12px 0}p{line-height:1.6;margin:6px 0}.el-tag{margin-right:10px}.el-dialog .el-select{min-width:220px}@media(max-width:700px){.condition{flex-wrap:wrap}.condition .el-select{min-width:150px}}</style>
